#!/usr/bin/env python3

from cyclopts import App

app = App(name="fileman")

@app.command
def upload(path: str) -> None:
    """Upload a file."""
    print(f"Would upload: {path}")

@app.command
def download(url: str, *, dest: str) -> None:
    """Download a file."""
    print(f"URL: {url}")
    print(f"Destination: {dest}")

if __name__ == "__main__":
